    @GameTest(environment="buildupmobtweaks:r4e2c_birth",structure=ARENA,maxTicks=55)
    public void nativeBirthChanceEndpointsAndNoLoadReroll(GameTestHelper h){floor(h);var c=BuildupMobTweaks.config().hostile.extended.illusioner_clone_chance;int old=c.get();var born=new ArrayList<Illusioner>();try{for(int chance:new int[]{0,1000}){c.accept(chance);var m=EntityTypes.ILLUSIONER.create(h.getLevel(),EntitySpawnReason.SPAWN_ITEM_USE);m.snapTo(h.absolutePos(new BlockPos(5+born.size()*4,2,6)),0,0);m.finalizeSpawn(h.getLevel(),h.getLevel().getCurrentDifficultyAt(m.blockPosition()),EntitySpawnReason.SPAWN_ITEM_USE,null);m.setNoAi(true);h.getLevel().addFreshEntity(m);h.assertTrue(m.getAttached(IllusionState.DATA).getBooleanOr("clone_trait",false)==(chance==1000),"Actual native birth honors endpoint chance");born.add(m);}}finally{c.accept(old);}h.runAtTickTime(30,()->{for(var m:born){var d=m.getAttached(IllusionState.DATA).copy();var n=CombatTestWorld.reload(h,m);h.assertTrue(n.getAttached(IllusionState.DATA).equals(d),"Native load never rerolls");clean(h,n);}proof("native_birth_endpoints",born.getFirst(),"0/1000 only, natural distribution NOT RUN");h.succeed();});}
